import uuid
from datetime import date

from sqlalchemy import CheckConstraint, Column, Uuid, text
from sqlmodel import Field, SQLModel

from app.infrastructure.persistence import models  # noqa: F401  (naming convention)


class ApodTable(SQLModel, table=True):
    """Stored APODs. The domain entity is ``app.domain.apod.models.Apod``."""

    __tablename__ = "apod"
    # Closed values as VARCHAR + named CHECK (ADR-0023): ck_apod_media_type.
    __table_args__ = (
        CheckConstraint("media_type IN ('image', 'video')", name="media_type"),
    )

    # Internal UUIDv7 key generated by PostgreSQL 18 (ADR-0023).
    id: uuid.UUID = Field(
        sa_column=Column(Uuid(), primary_key=True, server_default=text("uuidv7()"))
    )
    # One APOD per date: the unique constraint is uq_apod_apod_date.
    apod_date: date = Field(unique=True)
    title: str
    explanation: str
    media_type: str
    media_url: str
    copyright: str | None = None
